// Parity check: the TS engine must produce exactly the findings the Python
// engine produced for the same inputs. Usage (from frontend/):
//   npx tsx checks/parity.check.ts <cases.json>
// cases.json is generated by running scripts/parity_gen.py in the backend.

import { readFileSync } from "node:fs";
import { evaluateCase, itemState, overallStatus, type EvaluateInput } from "../src/local/engine";

interface Case {
  name: string;
  input: EvaluateInput;
  expected: { findings: unknown[]; status: string; states: Record<string, string> };
}

// Python builds the "conflicting values (a, b)" list from a set, so its order
// is unspecified. Compare that list order-insensitively; everything else exact.
function canon(findings: unknown[]): string {
  return JSON.stringify(findings).replace(
    /(widersprüchliche Werte am [\d.]+|conflicting values on [\d.]+) \(([^)]*)\)/g,
    (_m, head: string, list: string) => `${head} (${list
        .split(", ")
        .sort((a, b) => (a === "–" ? 1 : b === "–" ? -1 : Number(a) - Number(b)))
        .join(", ")})`,
  );
}

const cases = JSON.parse(readFileSync(process.argv[2], "utf8")) as Case[];
let failures = 0;
for (const c of cases) {
  const findings = evaluateCase(c.input);
  const got = canon(findings);
  const want = canon(c.expected.findings);
  const status = overallStatus(findings);
  const states = Object.fromEntries(Object.keys(c.expected.states).map((i) => [i, itemState(i, findings)]));
  const ok = got === want && status === c.expected.status && JSON.stringify(states) === JSON.stringify(c.expected.states);
  if (!ok) {
    failures += 1;
    if (failures <= 5) {
      console.log(`FAIL ${c.name}`);
      const g = findings as unknown[];
      const w = c.expected.findings;
      for (let i = 0; i < Math.max(g.length, w.length); i++) {
        if (canon([g[i]]) !== canon([w[i]])) {
          console.log("  ts:", JSON.stringify(g[i]));
          console.log("  py:", JSON.stringify(w[i]));
          break;
        }
      }
      if (status !== c.expected.status) console.log(`  status ts=${status} py=${c.expected.status}`);
    }
  }
}
const total = cases.reduce((n, c) => n + c.expected.findings.length, 0);
console.log(`${cases.length - failures}/${cases.length} cases identical (${total} findings compared)`);
process.exit(failures ? 1 : 0);
